     * dissolved and a `204` is returned.
     */
    fun requestStacksUnstack(
        owner: String,
        repo: String,
        stackNumber: Long,
        options: RequestOptions? = null,
    ): dev.octri.showcase.github.methods.Pulls.PullRequestStacksUnstackResponse {
        return dev.octri.showcase.github.methods.Pulls.pullRequestStacksUnstack(
            clientConfig,
            owner,
            repo,
            stackNumber,
            options,
        )
    }
